        } else {
            Hold::Released
        };
        self.by_sent_at.insert((entry.sent_at, arrival));
        self.messages.insert(
            arrival,
            Message {
                id: entry.id,
                body: entry.body,
                sent_at: entry.sent_at,
                receive_count: 0,
                first_received_at: None,
                placement,
                hold,
            },
        );
