enum Hold {
    Released,
    Delayed { until: Seconds },
    InFlight { until: Seconds, handle: ReceiptHandle },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum State {
    Visible,
    InFlight,
    Delayed,
}

#[derive(Debug)]
struct Message {
    id: MessageId,
    body: String,
    sent_at: Seconds,
    receive_count: u32,
    first_received_at: Option<Seconds>,
    placement: Option<Placement>,
    hold: Hold,
}

impl Message {
    fn state(&self, now: Seconds) -> State {
        match self.hold {
            Hold::Delayed { until } if now < until => State::Delayed,
            Hold::InFlight { until, .. } if now < until => State::InFlight,
            _ => State::Visible,
        }
    }
}

