        let delayed = Outgoing { delay: Some(Seconds::new(10)), ..outgoing("a") };
        ids.send(&mut queue, 0, delayed).unwrap();
        assert_eq!(queue.counts(Seconds::new(9)), Counts { visible: 0, in_flight: 0, delayed: 1 });
        assert_eq!(queue.counts(Seconds::new(10)), Counts { visible: 1, in_flight: 0, delayed: 0 });
        assert!(ids.receive(&mut queue, 9, 1, 30).delivered.is_empty());
        assert_eq!(bodies(&ids.receive(&mut queue, 10, 1, 30)), ["a"]);
    }

