git add -A && git commit -q -m "Route commands to queues in a broker

The rules that span queues (dead-letter targets, queue limits, deleting a
queue that others dead-letter into) and the global clock and id counters
need one owner. The broker also renders replies, so every response is
built from typed values rather than ad hoc JSON. Scenario tests drive it
through whole command lines." -m "Co-Authored-By: Claude Sonnet 5.5 <noreply@anthropic.com>" && cat >> src/lib.rs <<'EOF'

use std::io::{self, BufRead, Write};

use broker::Broker;

/// Answers every line of `input` with one response line on `output`, flushing
/// after each so a caller can read a response before sending the next command.
pub fn run(mut input: impl BufRead, mut output: impl Write) -> io::Result<()> {
    let mut broker = Broker::default();
    let mut line = Vec::new();
    loop {
        line.clear();
        if input.read_until(b'\n', &mut line)? == 0 {
            return Ok(());
        }
        if line.last() == Some(&b'\n') {
            line.pop();
        }
        let response = broker.respond(&line);
        output.write_all(response.as_bytes())?;
        output.write_all(b"\n")?;
        output.flush()?;
    }
}
EOF
cat > src/main.rs <<'EOF'
use std::io;
use std::process::ExitCode;

fn main() -> ExitCode {
    match miniq::run(io::stdin().lock(), io::stdout().lock()) {
        Ok(()) => ExitCode::SUCCESS,
        Err(error) => {
            eprintln!("miniq: {error}");
            ExitCode::FAILURE
        }
    }
}
EOF
cat > tests/cli.rs <<'EOF'
//! Runs the real binary to check the line protocol on stdin and stdout.

use std::io::Write;
use std::process::{Command, Stdio};

fn run_miniq(input: &[u8]) -> (String, Option<i32>) {
    let mut child = Command::new(env!("CARGO_BIN_EXE_miniq"))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .expect("the miniq binary starts");
    child
        .stdin
        .take()
        .expect("stdin is piped")
        .write_all(input)
        .expect("miniq reads its input");
    let output = child.wait_with_output().expect("miniq exits");
    (String::from_utf8(output.stdout).expect("output is UTF-8"), output.status.code())
}

#[test]
fn every_line_gets_one_response_in_order() {
    let (stdout, status) = run_miniq(b"{\"Command\": \"Tick\", \"Seconds\": 2}\n\nnot json\n{\"Command\": \"Tick\", \"Seconds\": 3}");
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines.len(), 4);
    assert_eq!(lines[0], r#"{"ok":true,"Now":2}"#);
    assert!(lines[1].starts_with(r#"{"ok":false,"error":{"code":"InvalidRequest""#));
    assert!(lines[2].starts_with(r#"{"ok":false,"error":{"code":"InvalidRequest""#));
    assert_eq!(lines[3], r#"{"ok":true,"Now":5}"#);
    assert!(stdout.ends_with('\n'));
    assert_eq!(status, Some(0));
}

#[test]
fn invalid_utf8_line_is_rejected_and_the_next_line_still_runs() {
    let (stdout, status) = run_miniq(b"{\"Command\": \"\xff\"}\n{\"Command\": \"Tick\", \"Seconds\": 1}\n");
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines.len(), 2);
    assert!(lines[0].contains("InvalidRequest"));
    assert_eq!(lines[1], r#"{"ok":true,"Now":1}"#);
    assert_eq!(status, Some(0));
}

#[test]
fn empty_input_produces_no_output() {
    assert_eq!(run_miniq(b""), (String::new(), Some(0)));
}

#[test]
fn filling_a_queue_to_its_limit_is_fast() {
    let mut input = String::from("{\"Command\": \"CreateQueue\", \"QueueName\": \"q\"}\n");
    for _ in 0..100_001 {
        input.push_str("{\"Command\": \"SendMessage\", \"QueueName\": \"q\", \"Body\": \"x\"}\n");
    }
    let (stdout, _) = run_miniq(input.as_bytes());
    let last = stdout.lines().last().expect("responses exist");
    assert!(last.contains("LimitExceeded"));
    assert_eq!(stdout.lines().count(), 100_002);
}
EOF
